	__models__GongNoteShape__00000000_.Identifier = `ref_models.Note01NavaidMessage`
	__models__GongNoteShape__00000000_.Body = `01. Navaid & Point Message & Temporality Story

An [models.AIXMBasicMessage] exchanges radio navigation aids and waypoints via [models.BasicMessageMemberAIXMPropertyType].
Each feature ([models.NavaidType], [models.DesignatedPointType]) is versioned over time by [models.NavaidTimeSliceType]
and [models.DesignatedPointTimeSliceType] slices bounded by ValidTime ([models.TimePrimitivePropertyType]).
`
	__models__GongNoteShape__00000000_.BodyHTML = `<p>01. Navaid &amp; Point Message &amp; Temporality Story
<p>An <a href="/models#AIXMBasicMessage">models.AIXMBasicMessage</a> exchanges radio navigation aids and waypoints via <a href="/models#BasicMessageMemberAIXMPropertyType">models.BasicMessageMemberAIXMPropertyType</a>.
Each feature (<a href="/models#NavaidType">models.NavaidType</a>, <a href="/models#DesignatedPointType">models.DesignatedPointType</a>) is versioned over time by <a href="/models#NavaidTimeSliceType">models.NavaidTimeSliceType</a>
and <a href="/models#DesignatedPointTimeSliceType">models.DesignatedPointTimeSliceType</a> slices bounded by ValidTime (<a href="/models#TimePrimitivePropertyType">models.TimePrimitivePropertyType</a>).
`
	__models__GongNoteShape__00000000_.X = 40.000000
	__models__GongNoteShape__00000000_.Y = 20.000000
	__models__GongNoteShape__00000000_.Width = 640.000000
