	__models__GongNoteShape__00000001_.Name = `02. Navaid, Component & Operational Status-Note02NavaidComponent`
	__models__GongNoteShape__00000001_.Identifier = `ref_models.Note02NavaidComponent`
	__models__GongNoteShape__00000001_.Body = `02. Navaid, Component & Operational Status Story

A [models.NavaidTimeSliceType] represents a composite navigation system (such as a VOR/DME, VORTAC, or ILS installation).
Physical equipment is linked via [models.NavaidComponentType], while availability and signal monitoring use
[models.NavaidOperationalStatusType], [models.NavaidEquipmentMonitoringType], and [models.AuthorityForNavaidEquipmentType].
`
	__models__GongNoteShape__00000001_.BodyHTML = `<p>02. Navaid, Component &amp; Operational Status Story
<p>A <a href="/models#NavaidTimeSliceType">models.NavaidTimeSliceType</a> represents a composite navigation system (such as a VOR/DME, VORTAC, or ILS installation).
Physical equipment is linked via <a href="/models#NavaidComponentType">models.NavaidComponentType</a>, while availability and signal monitoring use
<a href="/models#NavaidOperationalStatusType">models.NavaidOperationalStatusType</a>, <a href="/models#NavaidEquipmentMonitoringType">models.NavaidEquipmentMonitoringType</a>, and <a href="/models#AuthorityForNavaidEquipmentType">models.AuthorityForNavaidEquipmentType</a>.
`
