	__models__GongNoteShape__00000002_.Identifier = `ref_models.Note03RadioNavaids`
	__models__GongNoteShape__00000002_.Body = `03. En-Route Radio Navaids (VOR, DME, TACAN, NDB) Story

Individual radio transmitters ([models.VORTimeSliceType], [models.DMETimeSliceType], [models.TACANTimeSliceType], and [models.NDBTimeSliceType])
carry frequency/channel parameters, magnetic variation, 3D antenna coordinates ([models.ElevatedPointType]), and [models.NavaidOperationalStatusType].
`
	__models__GongNoteShape__00000002_.BodyHTML = `<p>03. En-Route Radio Navaids (VOR, DME, TACAN, NDB) Story
<p>Individual radio transmitters (<a href="/models#VORTimeSliceType">models.VORTimeSliceType</a>, <a href="/models#DMETimeSliceType">models.DMETimeSliceType</a>, <a href="/models#TACANTimeSliceType">models.TACANTimeSliceType</a>, and <a href="/models#NDBTimeSliceType">models.NDBTimeSliceType</a>)
carry frequency/channel parameters, magnetic variation, 3D antenna coordinates (<a href="/models#ElevatedPointType">models.ElevatedPointType</a>), and <a href="/models#NavaidOperationalStatusType">models.NavaidOperationalStatusType</a>.
`
	__models__GongNoteShape__00000002_.X = 40.000000
	__models__GongNoteShape__00000002_.Y = 20.000000
	__models__GongNoteShape__00000002_.Width = 640.000000
	__models__GongNoteShape__00000002_.Height = 124.000000
	__models__GongNoteShape__00000002_.IsHidden = false
	__models__GongNoteShape__00000002_.Matched = false
	__models__GongNoteShape__00000002_.IsExpanded = false
	__models__GongNoteShape__00000003_.Name = `04. ILS & MLS Precision Approach Navaids-Note04ILSMLS`
	__models__GongNoteShape__00000003_.Identifier = `ref_models.Note04ILSMLS`
	__models__GongNoteShape__00000003_.Body = `04. ILS & MLS Precision Approach Navaids Story

Precision landing guidance comprises [models.LocalizerTimeSliceType] (lateral course), [models.GlidepathTimeSliceType] (vertical descent slope),
and [models.MarkerBeaconTimeSliceType] (outer/middle/inner markers), each reporting serviceability via [models.NavaidOperationalStatusType].
`
	__models__GongNoteShape__00000003_.BodyHTML = `<p>04. ILS &amp; MLS Precision Approach Navaids Story
<p>Precision landing guidance comprises <a href="/models#LocalizerTimeSliceType">models.LocalizerTimeSliceType</a> (lateral course), <a href="/models#GlidepathTimeSliceType">models.GlidepathTimeSliceType</a> (vertical descent slope),
and <a href="/models#MarkerBeaconTimeSliceType">models.MarkerBeaconTimeSliceType</a> (outer/middle/inner markers), each reporting serviceability via <a href="/models#NavaidOperationalStatusType">models.NavaidOperationalStatusType</a>.
`
	__models__GongNoteShape__00000003_.X = 40.000000
	__models__GongNoteShape__00000003_.Y = 20.000000
	__models__GongNoteShape__00000003_.Width = 640.000000
	__models__GongNoteShape__00000003_.Height = 124.000000
