	__models__GongNoteShape__00000003_.IsExpanded = false
	__models__GongNoteShape__00000004_.Name = `05. Navigation Checkpoints (VOR & INS)-Note05Checkpoints`
	__models__GongNoteShape__00000004_.Identifier = `ref_models.Note05Checkpoints`
	__models__GongNoteShape__00000004_.Body = `05. Navigation Checkpoints (VOR & INS) Story

[models.CheckpointVORTimeSliceType] and [models.CheckpointINSTimeSliceType] specify designated aerodrome or airborne locations
([models.ElevatedPointType]) where pilots can verify VOR receiver bearing accuracy or align inertial navigation systems.
`
	__models__GongNoteShape__00000004_.BodyHTML = `<p>05. Navigation Checkpoints (VOR &amp; INS) Story
<p><a href="/models#CheckpointVORTimeSliceType">models.CheckpointVORTimeSliceType</a> and <a href="/models#CheckpointINSTimeSliceType">models.CheckpointINSTimeSliceType</a> specify designated aerodrome or airborne locations
(<a href="/models#ElevatedPointType">models.ElevatedPointType</a>) where pilots can verify VOR receiver bearing accuracy or align inertial navigation systems.
`
	__models__GongNoteShape__00000004_.X = 40.000000
	__models__GongNoteShape__00000004_.Y = 20.000000
