	__models__GongNoteShape__00000006_.Identifier = `ref_models.Note07DesignatedPoint`
	__models__GongNoteShape__00000006_.Body = `07. DesignatedPoint & SignificantPointInAirspace Story

[models.DesignatedPointTimeSliceType] defines published 5-letter ICAO waypoints and reporting points, while [models.SignificantPointInAirspaceTimeSliceType]
associates them with airspace entry/exit roles and segment references ([models.EnRouteSegmentPointType], [models.PointReferenceType]).
`
	__models__GongNoteShape__00000006_.BodyHTML = `<p>07. DesignatedPoint &amp; SignificantPointInAirspace Story
<p><a href="/models#DesignatedPointTimeSliceType">models.DesignatedPointTimeSliceType</a> defines published 5-letter ICAO waypoints and reporting points, while <a href="/models#SignificantPointInAirspaceTimeSliceType">models.SignificantPointInAirspaceTimeSliceType</a>
associates them with airspace entry/exit roles and segment references (<a href="/models#EnRouteSegmentPointType">models.EnRouteSegmentPointType</a>, <a href="/models#PointReferenceType">models.PointReferenceType</a>).
`
