	__models__GongNoteShape__00000007_.Identifier = `ref_models.Note08AngleDistance`
	__models__GongNoteShape__00000007_.Body = `08. AngleIndication & DistanceIndication Story

[models.AngleIndicationTimeSliceType] and [models.DistanceIndicationTimeSliceType] define published radials/bearings and DME distances
fixing a waypoint or navaid relative to a reference station via [models.AngleUseType] and [models.PointReferenceType].
`
	__models__GongNoteShape__00000007_.BodyHTML = `<p>08. AngleIndication &amp; DistanceIndication Story
<p><a href="/models#AngleIndicationTimeSliceType">models.AngleIndicationTimeSliceType</a> and <a href="/models#DistanceIndicationTimeSliceType">models.DistanceIndicationTimeSliceType</a> define published radials/bearings and DME distances
fixing a waypoint or navaid relative to a reference station via <a href="/models#AngleUseType">models.AngleUseType</a> and <a href="/models#PointReferenceType">models.PointReferenceType</a>.
`
